-
-    let params_vec: Vec<&dyn rusqlite::ToSql> = playlists
-        .iter()
-        .map(|s| s as &dyn rusqlite::ToSql)
-        .collect();
-    let mut shows = stmt
-        .query_map(rusqlite::params_from_iter(params_vec), |r| {
-            Ok(LibraryShow {
-                id: r.get(0)?,
-                playlist: r.get(1)?,
-                name: r.get(2)?,
-                root_path: r.get(3)?,
-                date_added: r.get(4)?,
